export const QA_PREFIX='wtstgj.qa.ui-repair-v002:';
export function namespaceStorage(storage,prefix=QA_PREFIX){if(!storage||!prefix)throw Error('QA storage unavailable');const keys=()=>{const out=[];for(let i=0;i<storage.length;i++){const key=storage.key(i);if(typeof key==='string'&&key.startsWith(prefix))out.push(key.slice(prefix.length))}return out};const api={getItem:k=>storage.getItem(prefix+String(k)),setItem:(k,v)=>storage.setItem(prefix+String(k),String(v)),removeItem:k=>storage.removeItem(prefix+String(k)),key:i=>keys()[Math.trunc(Number(i))]??null,clear:()=>{for(const k of keys())storage.removeItem(prefix+k)}};Object.defineProperty(api,'length',{get:()=>keys().length});return Object.freeze(api)}
export function installQAStorage(win){const stores=['localStorage','sessionStorage'].map(name=>({name,descriptor:Object.getOwnPropertyDescriptor(win,name),storage:win[name]}));for(const s of stores)if(s.descriptor&&!s.descriptor.configurable)throw Error('QA storage cannot be isolated');const facades=stores.map(s=>namespaceStorage(s.storage));let count=0;try{for(let i=0;i<stores.length;i++){Object.defineProperty(win,stores[i].name,{value:facades[i],configurable:true});count++;if(win[stores[i].name]!==facades[i])throw Error('QA storage isolation failed')}}catch(e){for(let i=0;i<count;i++){const s=stores[i];if(s.descriptor)Object.defineProperty(win,s.name,s.descriptor);else delete win[s.name]}throw e}}
